#include <cstdint>
#include <vector>

class MovingAverage {
  std::vector<int> ring_;          // last `size` values, fixed memory
  size_t next_ = 0, count_ = 0;
  int64_t sum_ = 0;                // int64: size * INT_MAX does not overflow
public:
  explicit MovingAverage(int size) : ring_(size) {}
  double next(int val) {
    if (count_ == ring_.size()) sum_ -= ring_[next_];   // window full: drop the oldest
    else ++count_;
    ring_[next_] = val;
    sum_ += val;
    next_ = (next_ + 1) % ring_.size();
    return static_cast<double>(sum_) / count_;
  }
};

