int visiblePoints(const std::vector<std::vector<int>>& points, int angle,
                  const std::vector<int>& loc) {
    const double PI = std::acos(-1.0);
    std::vector<double> ang;
    int same = 0;
    for (const auto& p : points) {
        int dx = p[0] - loc[0], dy = p[1] - loc[1];
        if (dx == 0 && dy == 0) { same++; continue; }
        ang.push_back(std::atan2((double)dy, (double)dx) * 180.0 / PI);
    }
    std::sort(ang.begin(), ang.end());
    int m = (int)ang.size();
    for (int i = 0; i < m; i++) ang.push_back(ang[i] + 360.0);
    int best = 0;
    for (int l = 0, r = 0; r < (int)ang.size(); r++) {
        while (ang[r] - ang[l] > angle + 1e-9) l++;
        best = std::max(best, r - l + 1);
    }
    return std::min(best, m) + same;
}

bool checkInclusion(const std::string& p, const std::string& s) {
    int k = (int)p.size(), n = (int)s.size();
    if (k == 0) return true;
    if (k > n) return false;
    std::array<int, 26> diff{};  // need - win
    for (char c : p) diff[c - 'a']++;
    int bad = 0;  // letters with diff != 0
    for (int d : diff) bad += (d != 0);
    auto add = [&](int c, int delta) {
        if (diff[c] == 0) bad++;
        diff[c] += delta;
        if (diff[c] == 0) bad--;
    };
    for (int i = 0; i < n; i++) {
        add(s[i] - 'a', -1);
        if (i >= k) add(s[i - k] - 'a', +1);
        if (bad == 0) return true;
    }
    return false;
}

