long long subarraysWithKDistinct(const std::vector<int>& a, int k) {
    auto atMost = [&](int m) -> long long {
        if (m < 0) return 0;
        std::unordered_map<int, int> cnt;
        long long total = 0;
        for (int l = 0, r = 0; r < (int)a.size(); r++) {
            if (cnt[a[r]]++ == 0) m--;
            while (m < 0)
                if (--cnt[a[l++]] == 0) m++;
            total += r - l + 1;
        }
        return total;
    };
    return atMost(k) - atMost(k - 1);
}

