int maxScore(const std::vector<int>& a, int k) {
    int n = (int)a.size(), w = n - k;
    long long total = 0, cur = 0;
    for (int x : a) total += x;
    for (int i = 0; i < w; i++) cur += a[i];
    long long mn = cur;
    for (int i = w; i < n; i++) {
        cur += a[i] - a[i - w];
        mn = std::min(mn, cur);
    }
    return (int)(total - mn);
}

std::vector<int> findSubstring(const std::string& s, const std::vector<std::string>& words) {
    std::vector<int> res;
    int n = (int)s.size(), m = (int)words.size(), w = (int)words[0].size();
    if (w == 0 || (long long)w * m > n) return res;
    std::unordered_map<std::string, int> need;
    for (const auto& x : words) need[x]++;
    for (int off = 0; off < w; off++) {
        std::unordered_map<std::string, int> win;
        int l = off, used = 0;
        for (int r = off; r + w <= n; r += w) {
            std::string cur = s.substr(r, w);
            auto it = need.find(cur);
            if (it == need.end()) { win.clear(); used = 0; l = r + w; continue; }
            win[cur]++; used++;
            while (win[cur] > it->second) { win[s.substr(l, w)]--; used--; l += w; }
            if (used == m) {
                res.push_back(l);
                win[s.substr(l, w)]--; used--; l += w;
            }
        }
    }
    std::sort(res.begin(), res.end());
    return res;
}

