#include <vector>
#include <unordered_map>

long long sumOfUniqueCounts(const std::vector<int>& a, int k) {
    std::unordered_map<int, int> freq;
    long long total = 0;
    int ones = 0;                                  // values with freq == 1
    auto add = [&](int x) {
        int f = ++freq[x];
        if (f == 1) ++ones; else if (f == 2) --ones;
    };
    auto remove = [&](int x) {
        int f = --freq[x];
        if (f == 0) --ones; else if (f == 1) ++ones;
    };
    for (int i = 0; i < (int)a.size(); ++i) {
        add(a[i]);
        if (i >= k) remove(a[i - k]);
        if (i >= k - 1) total += ones;
    }
    return total;
}

