#include <algorithm>

int longestProductEqualsLcm(const std::vector<int>& a) {
    int maxA = a.empty() ? 1 : *std::max_element(a.begin(), a.end());
    std::vector<int> spf(maxA + 1, 0);              // smallest prime factor sieve
    for (int i = 2; i <= maxA; ++i)
        if (spf[i] == 0)
            for (int j = i; j <= maxA; j += i)
                if (spf[j] == 0) spf[j] = i;
    std::vector<int> last(maxA + 1, -1);            // last index where prime p appeared
    int left = 0, best = 0;
    for (int r = 0; r < (int)a.size(); ++r) {
        for (int x = a[r]; x > 1; ) {
            int p = spf[x];
            while (x % p == 0) x /= p;
            left = std::max(left, last[p] + 1);     // p already used inside the window
            last[p] = r;
        }
        best = std::max(best, r - left + 1);
    }
    return best;
}

#include <vector>
#include <set>

std::vector<double> windowMedians(const std::vector<int>& a, int k) {
    std::multiset<int> lo, hi;          // lo: smaller half (size = hi or hi + 1)
    auto balance = [&] {
        if (lo.size() > hi.size() + 1) { hi.insert(*lo.rbegin()); lo.erase(std::prev(lo.end())); }
        else if (hi.size() > lo.size()) { lo.insert(*hi.begin()); hi.erase(hi.begin()); }
    };
    std::vector<double> out;
    for (int i = 0; i < (int)a.size(); ++i) {
        if (lo.empty() || a[i] <= *lo.rbegin()) lo.insert(a[i]); else hi.insert(a[i]);
        if (i >= k) {                                  // remove a[i - k]
            int x = a[i - k];
            if (x <= *lo.rbegin()) lo.erase(lo.find(x)); else hi.erase(hi.find(x));
        }
        balance();
        if (i >= k - 1)
            out.push_back(k % 2 ? *lo.rbegin()
                                : ((double)*lo.rbegin() + *hi.begin()) / 2.0);
    }
    return out;
}

