int shortestSubarrayAtLeastK(const std::vector<int>& a, long long K) {
    int n = a.size();
    std::vector<long long> P(n + 1, 0);            // prefix sums, 64-bit
    for (int i = 0; i < n; ++i) P[i + 1] = P[i] + a[i];
    std::deque<int> dq;                            // indices with increasing P
    int best = n + 1;
    for (int j = 0; j <= n; ++j) {
        while (!dq.empty() && P[j] - P[dq.front()] >= K) {
            best = std::min(best, j - dq.front());
            dq.pop_front();                        // can't do better for this start
        }
        while (!dq.empty() && P[dq.back()] >= P[j])
            dq.pop_back();                         // j is a better start
        dq.push_back(j);
    }
    return best <= n ? best : -1;
}

int maxBuildings(vector<int> ang, int fov) {
    int n = ang.size();
    if (n == 0) return 0;
    for (int& a : ang) a %= 360;
    sort(ang.begin(), ang.end());
    for (int i = 0; i < n; ++i) ang.push_back(ang[i] + 360);
    int best = 0;
    for (int i = 0, j = 0; i < n; ++i) {
        if (j < i) j = i;
        while (j + 1 < i + n && ang[j + 1] - ang[i] <= fov) ++j;
        best = max(best, j - i + 1);
    }
    return best;
}

string minWindowSubseq(const string& s, const string& t) {
    int n = s.size(), m = t.size(), bestLen = INT_MAX, bestStart = -1;
    for (int i = 0; i < n; ++i) {
        if (s[i] != t[0]) continue;
        int j = i, k = 0;
        for (; j < n; ++j)
            if (s[j] == t[k] && ++k == m) break;
        if (j == n) break;
        int end = j;
        for (k = m - 1; k >= 0; --j)
            if (s[j] == t[k]) --k;
        int start = j + 1;
        if (end - start + 1 < bestLen) { bestLen = end - start + 1; bestStart = start; }
        i = start;
    }
    return bestStart < 0 ? "" : s.substr(bestStart, bestLen);
}
